CREATE TRIGGER app_payload_root_app_saved_content_metadata_hash_insert BEFORE INSERT ON app_saved_content WHEN EXISTS(SELECT 1 FROM app_payload_uploads u JOIN app_payload_objects o ON o.hash=u.hash WHERE u.hash=NEW.metadata_hash AND (u.done<>1 OR o.complete<>1)) BEGIN SELECT RAISE(ABORT,'Unpublished payload reference'); END;
